function menu(){mode='menu';$('#combat').hidden=true;$('#drawer').hidden=true;panel(`<div class="grid"><div><span class="eyebrow">TACTICAL DUNGEON / BROWSER RPG</span><h1>NEON<br><em>LABYRINTH</em></h1><p class="muted">Комплекс проснулся. Выход охраняет Хранитель.<br>Исследуй с AI. Возвращайся свободно. Собери свой стиль.</p><div class="cards"><div class="card"><strong>05</strong>противников</div><div class="card"><strong>03</strong>неизвестных</div><div class="card"><strong>01</strong>Хранитель</div></div><span class="badge">SEARCH · CSP · MINIMAX</span></div><div><a class="campaign-link" href="campaign.html">НОВАЯ КАМПАНИЯ · ПОСЛЕДНИЙ МАРШРУТ →</a><h3>КЛАССИЧЕСКИЙ ЗАБЕГ</h3><label for="seed">КОД КОМПЛЕКСА / SEED</label><input id="seed" maxlength="32" value="${Math.random().toString(36).slice(2,9).toUpperCase()}"><label for="size">МАСШТАБ ЛАБИРИНТА</label><select id="size"><option value="21">Компактный · 21 × 21</option><option value="25" selected>Стандартный · 25 × 25</option><option value="31">Большой · 31 × 31</option></select><label for="difficulty">ТАКТИЧЕСКАЯ СЛОЖНОСТЬ</label><select id="difficulty"><option value="2">Исследователь · глубина 2</option><option value="4" selected>Тактик · глубина 4</option><option value="6">Эксперт · глубина 6</option></select><div class="row"><button class="primary" id="start">НАЧАТЬ ЗАБЕГ →</button><button id="help">?</button></div><p class="muted">Без загрузок и аккаунтов. Прогресс текущего забега сохраняется на этом устройстве.</p><button id="resume" ${localStorage.getItem('neonSave')?'':'hidden'}>ПРОДОЛЖИТЬ ЗАБЕГ</button></div></div>`);$('#start').onclick=()=>start();$('#help').onclick=()=>help(menu);$('#resume').onclick=load}
function start(){$('#devBtn').textContent='DEV · F2';currentEvent=null;runStats={launches:{},exhaustion:0,manual:0,algorithm:0};lastLoss=null;pendingRoute=null;battleStats=null;near=null;target=null;autoIgnore=null;seed=$('#seed').value.trim()||'NEON';difficulty=+$('#difficulty').value;try{map=generate(seed,+$('#size').value)}catch{toast('Не удалось создать карту. Попробуйте другой seed.');return}player={x:1.5,y:1.5,hp:100,max:100,energy:3,atk:10,armor:0,potions:2,coins:12,weapon:'Импульсный клинок',suit:'Без брони',module:'Без модуля',passives:{}};kills=0;events=0;elapsed=0;walk=0;autoWalk=false;route=[];routeInfo=null;battle=null;log=[];started=true;cam={x:player.x*TILE,y:player.y*TILE};mode='explore';paused=false;bossAwake=false;prepared=false;firstStepDone=false;firstStepDistance=0;fogLevels=[];keys={};visited=Array(map.cells.length).fill(false);visited[cell()]=true;explored=Array(map.cells.length).fill(false);visible=new Set();fx=[];deaths=[];lastReveal=-1;reveal();overlay.innerHTML='';save();help(()=>{overlay.innerHTML='';firstStepHint()})}
function firstStepHint(){panel('<span class="eyebrow">КАЛИБРОВКА НАВИГАТОРА / ПЕРВЫЙ ШАГ</span><h2>Первый маршрут — с навигатором.</h2><p>Выберите объект на карте, затем алгоритм. Для первого выхода подойдёт <b>DFS — бесплатно</b>.</p><p class="muted">Пройдите хотя бы один шаг по маршруту. После этого WASD или стрелки позволят свободно ходить по исследованной местности. К неизвестной цели всегда можно отправиться с помощью алгоритма из текущей позиции.</p><button class="primary" id="firstRoute">ВЫБРАТЬ ЦЕЛЬ И АЛГОРИТМ →</button>');$('#firstRoute').onclick=()=>{overlay.innerHTML='';openMap()}}
function help(back){panel('<span class="eyebrow">НОВЫЙ ПРОТОКОЛ / 02</span><h2>Разведка. Карты. Пять печатей.</h2><div class="grid"><div><h3>НАВИГАТОР И СВОБОДНОЕ ДВИЖЕНИЕ</h3><p>Откройте карту M или нажмите маркер объекта прямо в тумане. Выберите DFS, BFS, UCS или A*: персонаж сам пойдёт к объекту по лабиринту.</p><p class="muted">DFS бесплатен. Остальные методы стоят кредиты. Противники, подарки, события и ловушки видны даже в тумане. Скрыты только стены и коридоры: они открываются при прохождении. Навигатор рассчитывает путь по полному плану комплекса. Первый шаг — через алгоритм. Затем WASD или стрелки — движение по изученным клеткам без раскрытия тумана. Новая территория открывается только при движении по алгоритму. Новый маршрут запускается из текущей позиции.</p></div><div><h3>ТАКТИЧЕСКИЕ КАРТЫ</h3><p>Возврат по пройденным клеткам не тратит HP. Первый проход: 0.6 HP за пол, 1.8 за завал, 3 за опасную зону. Враг объявляет следующий ход. Выберите карту атаки, пробития, защиты или лечения. Эффекты появляются над тем, кто их получает.</p><p class="muted">Победите всех 5 противников: только тогда появится Хранитель. Перед финалом доступна одна подготовка. Q — зелье, E — объект, Space — остановка, Esc — пауза.</p></div></div><button class="primary" id="ok">НАЧАТЬ РАЗВЕДКУ →</button>');$('#ok').onclick=back}
function save(){if(started&&mode==='explore')try{localStorage.setItem('neonSave',JSON.stringify({version:2,map,player,kills,events,elapsed,seed,difficulty,walk,explored,bossAwake,prepared,firstStepDone,firstStepDistance,visited,runStats}))}catch{}}
function validSave(s){const m=s?.map,p=s?.player;if(s?.version!==2||!Array.isArray(s.explored)||s.explored.length!==m?.cells?.length||!s.explored.every(v=>typeof v==='boolean')||!m||!p||![21,25,31].includes(m.n)||!Array.isArray(m.cells)||m.cells.length!==m.n*m.n||!m.cells.every(x=>[0,1,3,5].includes(x))||!Array.isArray(m.objects)||m.objects.length!==9||!m.csp)return false;if(!m.objects.every(o=>Number.isInteger(o.id)&&o.id>=0&&o.id<m.cells.length&&m.cells[o.id]&&['boss','cache','enemy','trap','quiz','merchant','medic','drone','terminal'].includes(o.type)))return false;if(!['x','y','hp','max','energy','atk','armor','potions','coins'].every(k=>Number.isFinite(p[k])))return false;if(p.hp<=0||p.hp>p.max||p.energy<0||p.energy>3||!Number.isInteger(p.energy)||p.coins<0||p.potions<0||p.atk<=0||p.armor<0||p.x<0||p.y<0||p.x>=m.n||p.y>=m.n||!m.cells[Math.floor(p.y)*m.n+Math.floor(p.x)])return false;return typeof s.seed==='string'&&s.seed.length<=32&&[2,4,6].includes(s.difficulty)&&['kills','events','elapsed','walk'].every(k=>Number.isFinite(s[k])&&s[k]>=0)}
function load(){try{let s=JSON.parse(localStorage.getItem('neonSave'));if(s&&s.version!==2){localStorage.setItem('neonSaveLegacy',JSON.stringify(s));localStorage.removeItem('neonSave');toast('Сохранение предыдущей версии. Начните новый забег.');return}if(!validSave(s))throw 0;({map,player,kills,events,elapsed,seed,difficulty,walk,explored,bossAwake,prepared}=s);visited=Array.isArray(s.visited)&&s.visited.length===map.cells.length&&s.visited.every(v=>typeof v==='boolean')?s.visited:explored.map((v,i)=>v&&!!map.cells[i]);visited[cell()]=true;player.passives=player.passives||{};runStats=s.runStats&&typeof s.runStats==='object'?s.runStats:{launches:{},exhaustion:0,manual:0,algorithm:0};runStats.launches??={};$('#devBtn').textContent=runStats.devUsed?'DEV* · F2':'DEV · F2';lastLoss=null;currentEvent=null;pendingRoute=null;firstStepDone=(typeof s.firstStepDone==='boolean'?s.firstStepDone:s.walk>0)||s.firstStepDistance>=.5;firstStepDistance=Number.isFinite(s.firstStepDistance)?Math.max(0,Math.min(1,s.firstStepDistance)):0;fogLevels=[];keys={};started=true;mode='explore';paused=false;autoWalk=false;route=[];routeInfo=null;battleStats=null;near=null;battle=null;overlay.innerHTML='';cam={x:player.x*TILE,y:player.y*TILE};lastReveal=-1;reveal(false);toast('Протокол восстановлен.');if(kills===5&&!prepared)checkBoss();else if(!firstStepDone)firstStepHint()}catch{localStorage.removeItem('neonSave');toast('Сохранение повреждено. Начните новый забег.')}}
function pause(){if(mode==='menu')return;if(overlay.innerHTML){if(overlay.dataset.kind==='pause'){overlay.innerHTML='';overlay.dataset.kind='';paused=false}return}paused=true;keys={};overlay.dataset.kind='pause';panel(`<span class="eyebrow">ПРОТОКОЛ ПРИОСТАНОВЛЕН</span><h2>Тишина перед следующим шагом.</h2><p class="muted">${mode==='combat'?'Бой приостановлен. Автосохранение сделано перед встречей.':'Забег сохранён на этом устройстве.'}</p><div class="row"><button class="primary" id="continue">ПРОДОЛЖИТЬ</button><button id="sound">ЗВУК: ${sound?'ВКЛ':'ВЫКЛ'}</button><button id="leave" class="danger">В МЕНЮ</button></div>`);$('#continue').onclick=()=>{overlay.innerHTML='';overlay.dataset.kind='';paused=false};$('#sound').onclick=e=>{sound=!sound;e.target.textContent='ЗВУК: '+(sound?'ВКЛ':'ВЫКЛ')};$('#leave').onclick=()=>{panel('<h2>Вернуться в меню?</h2><p class="muted">Исследование сохранено. Незавершённый бой начнётся заново.</p><div class="row"><button id="yes" class="danger">В МЕНЮ</button><button id="no">ОСТАТЬСЯ</button></div>');$('#yes').onclick=()=>{paused=false;overlay.dataset.kind='';menu()};$('#no').onclick=()=>{overlay.innerHTML='';overlay.dataset.kind='';paused=false}};save()}
$('#pauseBtn').onclick=pause;$('#mapBtn').onclick=openMap;$('#aiBtn').onclick=ai;
function openMap(){if(mode!=='explore'||paused)return;if(overlay.innerHTML){if(overlay.dataset.kind==='map'){overlay.innerHTML='';overlay.dataset.kind=''}return}cancelRoute();overlay.dataset.kind='map';keys={};target=null;panel(`<span class="eyebrow">НАВИГАЦИЯ / ОБЪЕКТЫ В ТУМАНЕ</span><h2>${firstStepDone?'Куда отправится разведчик?':'Первый шаг: выберите цель и алгоритм'}</h2><div class="maplayout"><div><div class="mapwrap"><canvas id="minimap" width="620" height="620"></canvas></div><div class="legend">● вы　◆ подарок　E враг　! ловушка　? событие　B босс<br>Все активные объекты видны. Стены и коридоры в тумане скрыты.</div></div><div><span class="label">${player.coins} CR</span><p id="targetText" class="muted">Нажмите противника, подарок, ловушку или событие — даже в тумане.</p><div class="routeBtns">${[['dfs','DFS',0],['bfs','BFS',2],['ucs','UCS',3],['astar','A*',3]].map(([a,n,p])=>`<button data-alg="${a}" data-price="${p}" disabled><b>${n}</b><span>${p?p+' CR':'БЕСПЛАТНО'}</span></button>`).join('')}</div><div id="routeStats">${routeInfo?routeInfo.alg.toUpperCase()+': '+(routeInfo.path.length-1)+' шагов · '+Number(routeInfo.cost).toFixed(2)+' оценки':''}</div><p class="muted">Нажмите алгоритм — герой сам пойдёт к цели по лабиринту. Навигатор знает план комплекса; вы открываете коридоры по мере движения.</p><button id="speedMap">СКОРОСТЬ ×${speed}</button><button id="mapClose" class="primary">ЗАКРЫТЬ · M</button></div></div>`);drawMini();$('#speedMap').onclick=e=>{speed=speed===1?2:1;e.target.textContent='СКОРОСТЬ ×'+speed};$('#mapClose').onclick=()=>{overlay.innerHTML='';overlay.dataset.kind=''};$('#minimap').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*map.n),y=Math.floor((e.clientY-r.top)/r.height*map.n),id=y*map.n+x;if(!selectable(id)){toast('Выберите объект в тумане или открытую клетку.');return}target=id;$('#targetText').textContent='Цель: ['+x+', '+y+']';showRouteOptions(id);drawMini()};document.querySelectorAll('[data-alg]').forEach(b=>b.onclick=()=>travel(target,b.dataset.alg,+b.dataset.price))}
function travel(id,alg,price){if(id===null||!selectable(id)||player.coins<price||mode!=='explore')return false;const result=search(navigationMap(map,visited,player.passives),cell(),id,alg);if(result.path.length<2){toast('Вы уже здесь или путь недоступен.');return false}keys={};pendingRoute=null;player.coins-=price;route=result.path;routeInfo={...result,alg,forecast:routeForecast(map,result.path,visited,player)};runStats.launches[alg]=(runStats.launches[alg]||0)+1;autoIndex=0;autoIgnore=map.objects.find(o=>activeObject(o)&&Math.hypot(o.id%map.n+.5-player.x,Math.floor(o.id/map.n)+.5-player.y)<1.3)?.id??null;autoWalk=true;overlay.innerHTML='';overlay.dataset.kind='';save();beep(650);toast(alg.toUpperCase()+' · '+(route.length-1)+' шагов · '+routeInfo.forecast.loss.toFixed(1)+' HP на переход');return true}
function showRouteOptions(id){const obj=map.objects.find(o=>o.id===id&&activeObject(o));$('#targetText').textContent=(obj?objectName(obj)+' · ':'Цель · ')+'['+id%map.n+', '+Math.floor(id/map.n)+']';document.querySelectorAll('[data-alg]').forEach(b=>{const r=search(navigationMap(map,visited,player.passives),cell(),id,b.dataset.alg),f=routeForecast(map,r.path,visited,player);b.disabled=player.coins<+b.dataset.price||r.path.length<2;b.innerHTML='<b>'+b.dataset.alg.toUpperCase().replace('ASTAR','A*')+'</b><span>'+(+b.dataset.price?b.dataset.price+' CR':'БЕСПЛАТНО')+'</span><small>'+Math.max(0,r.path.length-1)+' шагов · −'+f.loss.toFixed(1)+' HP</small>'});$('#routeStats').innerHTML='Прогноз учитывает только первый проход. Бои, события и награды могут изменить HP. Возврат по пройденным клеткам бесплатен.'}
function objectName(o){return ({enemy:names[o.kind],boss:'Хранитель',cache:'Подарок',trap:'Ловушка',quiz:'Викторина',merchant:'Торговец',medic:'Медстанция',drone:'Повреждённый дрон',terminal:'Терминал'})[o.type]||'Событие'}
function reveal(expand=true){if(!map||!player)return;if(explored.length!==map.cells.length)explored=Array(map.cells.length).fill(false);visible=new Set(vision(map,player.x,player.y));if(expand){for(const id of visible)explored[id]=true}else visible=new Set([...visible].filter(id=>explored[id]));lastReveal=cell()}
function selectable(id){return Number.isInteger(id)&&id>=0&&id<map.cells.length&&!!map.cells[id]&&(!!explored[id]||map.objects.some(o=>o.id===id&&activeObject(o)))}
function activeObject(o){return !o.done&&(o.type!=='boss'||bossAwake)}
function frontier(id){const x=id%map.n,y=Math.floor(id/map.n);return [[1,0],[-1,0],[0,1],[0,-1]].some(([a,b])=>x+a>=0&&y+b>=0&&x+a<map.n&&y+b<map.n&&!explored[(y+b)*map.n+x+a])}

function drawMini(){const c=$('#minimap');if(!c)return;const g=c.getContext('2d'),sz=c.width/map.n;g.fillStyle='#030712';g.fillRect(0,0,c.width,c.height);for(let i=0;i<map.cells.length;i++){if(!explored[i])continue;g.fillStyle=map.cells[i]?(visible.has(i)?'#32485e':'#1c2a3e'):'#0e1522';if(map.cells[i]>1)g.fillStyle=map.cells[i]===3?'#645231':'#633449';g.fillRect(i%map.n*sz,Math.floor(i/map.n)*sz,sz-1,sz-1);if(map.cells[i]&&frontier(i)){g.fillStyle='#55efdb';g.fillRect((i%map.n+.4)*sz,(Math.floor(i/map.n)+.4)*sz,sz*.2,sz*.2)}}for(const i of route){if(!explored[i])continue;g.fillStyle='#55efdb80';g.fillRect((i%map.n+.3)*sz,(Math.floor(i/map.n)+.3)*sz,sz*.4,sz*.4)}for(const o of map.objects)if(activeObject(o)){g.fillStyle=o.type==='enemy'?'#f559a7':o.type==='boss'?'#ff5566':o.type==='cache'?'#eac47b':'#a68bfa';g.beginPath();g.arc((o.id%map.n+.5)*sz,(Math.floor(o.id/map.n)+.5)*sz,sz*.40,0,7);g.fill();g.fillStyle='#0c101e';g.font='bold '+Math.max(9,sz*.65)+'px monospace';g.textAlign='center';g.fillText(o.type==='enemy'?'E':o.type==='cache'?'◆':o.type==='trap'?'!':o.type==='boss'?'B':'?',(o.id%map.n+.5)*sz,(Math.floor(o.id/map.n)+.73)*sz)}g.fillStyle='#fff';g.fillRect(player.x*sz-sz*.22,player.y*sz-sz*.22,sz*.44,sz*.44);if(target!==null){g.strokeStyle='#fff';g.lineWidth=2;g.strokeRect(target%map.n*sz,Math.floor(target/map.n)*sz,sz,sz)}}
function ai(){if(!started||mode==='menu')return;const d=$('#drawer');d.hidden=!d.hidden;if(d.hidden)return;d.innerHTML=`<button class="close">×</button><span class="eyebrow">СИСТЕМА / AI</span><h2>Под капотом</h2><h3>02 / SEARCH</h3><p class="muted">DFS ищет один путь. BFS минимизирует шаги. UCS минимизирует стоимость. A* использует стоимость и манхэттенскую эвристику.</p>${routeInfo?`<div class="stat">Алгоритм <b>${routeInfo.alg.toUpperCase()}</b></div><div class="stat">Стоимость <b>${Number(routeInfo.cost).toFixed(2)}</b></div><div class="stat">Исследовано <b>${routeInfo.visits.length}</b></div>`:'<p class="muted">Купите маршрут на карте для измерений.</p>'}<h3>03 / CSP</h3><p class="muted">Переменные: 9 позиций. Домены: достижимые клетки. Ограничения: уникальность, безопасный старт, расстояние до босса и между врагами, доступный тайник.</p><div class="stat">Проверено кандидатов <b>${map.csp.nodes}</b></div><div class="stat">Возвратов <b>${map.csp.backs}</b></div><div class="stat">Ограничения <b>СОБЛЮДЕНЫ</b></div><h3>04 / ADVERSARIAL SEARCH</h3><p class="muted">Minimax оценивает здоровье, энергию и лечение. Alpha-Beta отсекает невыгодные ветви. Поиск использует только открытое состояние боя.</p>${battleStats?Object.entries({Действие:actNames[battleStats.action],Глубина:battleStats.depth,Состояний:battleStats.nodes,Отсечений:battleStats.cuts}).map(([a,b])=>`<div class="stat">${a}<b>${b}</b></div>`).join(''):'<p class="muted">Данные появятся после хода противника.</p>'}<h3>ЭКИПИРОВКА</h3><p class="muted">${player.weapon}<br>${player.suit}<br>${player.module}<br>${Object.keys(player.passives||{}).filter(k=>player.passives[k]&&RELICS[k]).map(k=>RELICS[k].name).join(' · ')||'Реликвий пока нет'}<br>Урон ${player.atk} · Броня ${player.armor}</p>`;d.querySelector('.close').onclick=()=>d.hidden=true}
function cell(){return Math.floor(player.y)*map.n+Math.floor(player.x)}
function cancelRoute(){autoWalk=false;pendingRoute=null;route=[]}
function suspendRoute(o){if(autoWalk&&route.length)pendingRoute=o.id;autoWalk=false}
function resumeRoute(o){if(pendingRoute===null||(o&&o.id!==pendingRoute)||mode!=='explore'||paused||overlay.innerHTML||!route.length)return false;autoIgnore=pendingRoute;pendingRoute=null;autoWalk=true;keys={};return true}
function encounter(o){if(mode!=='explore'||overlay.innerHTML||!activeObject(o))return;if(o.type==='enemy'||o.type==='boss'){suspendRoute(o);save();mode='combat';const boss=o.type==='boss',kind=o.kind,hp=boss?115:kind===0?38:kind===1?32:36;const enemy={hp,max:hp,atk:boss?14:kind===1?12:9,armor:boss?3:kind===0?4:1,energy:2,potions:0,guard:false,boss,phase2:false,role:boss?'boss':['sentinel','berserker','technician'][kind]};battle={s:[{...player,guard:false,shieldUsed:false},enemy],object:o,name:boss?'Хранитель':names[kind],boss,phase:1,charge:false};planIntent();enemyTurn=false;log=['Контакт установлен. Выберите действие.'];$('#combat').hidden=false;beep(160,.2);renderBattle()}else event(o)}
function renderBattle(){if(!battle)return;const[p,e]=battle.s;const desc={attack:'Урон '+p.atk+'. Возвращает 1 энергию.',heavy:'Урон '+Math.round(p.atk*1.8)+'. Стоит 2 энергии.',pierce:'Урон '+Math.round(p.atk*.85)+'. Игнорирует броню.',guard:p.lastAction==='guard'?'Сначала сыграйте другую карту.':'Следующий урон уменьшен вдвое.',heal:'Восстанавливает до 25 HP.'};$('#combat').innerHTML=`<div class="battle-head"><div><span class="eyebrow">${battle.boss?'ФИНАЛЬНЫЙ ПРОТОКОЛ':'ТАКТИЧЕСКИЙ КОНТАКТ'}</span><h3>${battle.name} <span class="muted">${Math.ceil(e.hp)} / ${e.max} HP · броня ${e.armor}</span></h3></div><div class="intent"><img src="assets/cards/${battle.intent==='repair'?'heal':battle.intent}.svg" alt=""><span>Следующий ход<br><b>${actNames[battle.intent]}</b></span></div></div><p class="enemy-trait">${enemyTrait(e)}</p><div class="actions">${[['attack','Атака','+1 энергия'],['heavy','Сильный удар','−2 энергии'],['pierce','Пробитие','−1 энергия'],['guard','Защита','+2 энергии'],['heal','Лечение',p.potions+' зелий']].map(([a,n,c])=>`<button class="battle-card ${a}" data-action="${a}" title="${desc[a]}" ${enemyTurn||!actions(battle.s,0).includes(a)?'disabled':''}><span class="card-cost">${c}</span><img src="assets/cards/${a}.svg" alt="${n}"><strong>${n}</strong><span class="card-desc">${desc[a]}</span></button>`).join('')}</div><div id="battlelog">${log.slice(-2).join('<br>')}</div>`;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>turn(b.dataset.action))}
function enemyTrait(e){if(e.boss)return e.phase2?'Фаза II: урон Хранителя повышен. Следите за объявленным ходом.':'При 40% HP Хранитель перейдёт во вторую фазу.';if(e.role==='sentinel')return e.charged?'Заряд +5 к следующему удару! Пробитие снимет заряд.':'Страж заряжает следующий удар после защиты. Пробитие сбивает заряд.';if(e.role==='berserker')return e.enraged?'Ярость активна: урон +3.':'На половине HP Берсерк получает +3 урона. Добейте его быстро.';return e.repairing?'Ремонт готов: +12 HP перед следующим ходом. Прервите сильным ударом или пробитием!':'Техник может подготовить один ремонт. Сильный удар и пробитие прерывают подготовку.'}
function offerRelic(o){const key=Object.keys(RELICS).find(k=>!player.passives?.[k]);if(!key)return;const r=RELICS[key],b=document.createElement('button');b.id='lootRelic';b.className='choice reward-card';b.innerHTML='<img src="assets/cards/'+r.art+'.svg" alt=""><span>'+r.name+'<small>'+r.text+'</small></span>';overlay.querySelector('.panel').appendChild(b);b.onclick=()=>{player.passives??={};player.passives[key]=true;overlay.innerHTML='';save();toast('Реликвия: '+r.name);checkBoss();resumeRoute(o)}}
function relicChoices(o){const available=Object.entries(RELICS).filter(([k])=>!player.passives?.[k]);panel('<span class="eyebrow">РЕЛИКВИИ / СТИЛЬ ИГРЫ</span><h2>Выберите свой модуль.</h2>'+available.map(([k,r])=>'<button class="choice reward-card" id="relic_'+k+'"><img src="assets/cards/'+r.art+'.svg" alt=""><span>'+r.name+'<small>'+r.text+'</small></span></button>').join('')+'<button id="relicBack">НАЗАД</button>');for(const[k,r]of available)$('#relic_'+k).onclick=()=>{player.passives??={};player.passives[k]=true;doneEvent(o,'Реликвия: '+r.name)};$('#relicBack').onclick=()=>event(o)}
function planIntent(){if(!battle)return;battleStats=choose(battle.s,difficulty,true,true);battle.intent=battleStats.action}
function effect(who,action,amount=0){if(!battle)return;const o=battle.object;fx.push({x:who===0?player.x:o.id%map.n+.5,y:who===0?player.y:Math.floor(o.id/map.n)+.5,action,amount,age:0,life:1.25});}

function turn(a){if(enemyTurn||paused||!battle||!actions(battle.s,0).includes(a))return;const prev=battle.s[0].hp,phase=battle.s[1].phase2;battle.s=step(battle.s,0,a);effect(a==='guard'||a==='heal'?0:1,a,a==='heal'?battle.s[0].hp-prev:battle.s.damage);if(battle.s.interrupted)log.push('Ремонт прерван!');if(battle.s[0].hp>prev&&a!=='heal')effect(0,'heal',battle.s[0].hp-prev);log.push('Вы: '+actNames[a]+(battle.s.damage?' · '+battle.s.damage+' урона':''));if(!phase&&battle.s[1].phase2)log.push('Хранитель: фаза II. Мощность повышена.');flash=.15;beep(a==='guard'?400:700);sync();if(battle.s[1].hp<=0){winBattle();return}enemyTurn=true;const activeBattle=battle;renderBattle();setTimeout(()=>{if(battle===activeBattle)enemyMove()},650)}
function enemyMove(){if(!battle||mode!=='combat')return;if(paused||overlay.innerHTML){const waitingBattle=battle;setTimeout(()=>{if(battle===waitingBattle)enemyMove()},150);return}const a=battle.intent,prev=battle.s[1].hp;battle.s=step(battle.s,1,a);effect(a==='guard'||a==='heal'||a==='repair'?1:0,a==='repair'?'guard':a,a==='heal'?battle.s[1].hp-prev:battle.s.damage);if(battle.s.shieldTriggered)log.push('Аварийный щит поглотил половину удара.');if(battle.s.repaired)effect(1,'heal',battle.s.repaired);log.push('Враг: '+actNames[a]+(battle.s.damage?' · '+battle.s.damage+' урона':''));sync();flash=.25;beep(180);enemyTurn=false;if(player.hp<=0){finish(false);return}planIntent();renderBattle()}

function sync(){const p=battle.s[0];for(const k of ['hp','energy','potions'])player[k]=p[k]}
function winBattle(){const o=battle.object,boss=battle.boss;sync();deaths.push({x:o.id%map.n+.5,y:Math.floor(o.id/map.n)+.5,type:o.type,kind:o.kind,age:0});o.done=true;$('#combat').hidden=true;battle=null;mode='explore';if(!boss)kills++;const coins=boss?25:8;player.coins+=coins;player.energy=3;if(boss){finish(true);return}player.hp=Math.min(player.max,player.hp+8);if(kills%2===0)player.potions++;toast(`Победа! +${coins} CR · восстановлено 8 HP${kills%2===0?' · +1 зелье':''}`);save();beep(900,.2);panel('<span class="eyebrow">ПОБЕДА / ТРОФЕИ</span><h2>Система противника разобрана.</h2><p class="muted">Кредиты уже получены. Выберите один дополнительный ресурс.</p><button class="choice" id="lootAtk">Энергоячейка · урон +2</button><button class="choice" id="lootArmor">Бронепластина · броня +1</button><button class="choice" id="lootHeal">Медкомплект · восстановить 25 HP</button>');$('#lootAtk').onclick=()=>{player.atk+=2;player.weapon='Усиленный клинок';overlay.innerHTML='';save();toast('Урон повышен на 2.');checkBoss();resumeRoute(o)};$('#lootArmor').onclick=()=>{player.armor++;player.suit='Усиленная броня';overlay.innerHTML='';save();toast('Броня повышена на 1.');checkBoss();resumeRoute(o)};$('#lootHeal').onclick=()=>{player.hp=Math.min(player.max,player.hp+25);overlay.innerHTML='';save();toast('Медкомплект: +25 HP');checkBoss();resumeRoute(o)};offerRelic(o);}
function checkBoss(){if(kills<5||prepared)return;bossAwake=true;autoWalk=false;beep(120,.5);panel('<span class="eyebrow">ПЯТЬ ПЕЧАТЕЙ СНЯТЫ</span><h2>Хранитель пробуждён.</h2><p>Свет комплекса изменился. Финальная комната активна. Выберите одну подготовку перед боем.</p><button class="choice" id="prepHeal">Медстанция · полностью восстановить HP</button><button class="choice" id="prepPotion">Запас · получить 3 зелья</button><button class="choice" id="prepWeapon">Перегрузка · урон +4</button>');const done=()=>{prepared=true;overlay.innerHTML='';save();toast('Хранитель ждёт в глубине комплекса. Продолжайте разведку.');resumeRoute();};$('#prepHeal').onclick=()=>{player.hp=player.max;done()};$('#prepPotion').onclick=()=>{player.potions+=3;done()};$('#prepWeapon').onclick=()=>{player.atk+=4;done()};save()}
function event(o){currentEvent=o;suspendRoute(o);keys={};if(o.type==='cache'){panel(`<span class="eyebrow">ТАЙНИК / СНАРЯЖЕНИЕ</span><h2>То, что оставили до тебя.</h2><p class="muted">Выберите одну награду. Остальное будет заблокировано.</p><button class="choice" id="weapon">Импульсный клинок MK II · урон ${player.atk} → ${player.atk+3}</button><button class="choice" id="armor">Композитная броня · броня ${player.armor} → ${player.armor+2}</button><button class="choice" id="module">Модуль жизни · максимум HP +15, восстановление 25 HP</button><button class="choice" id="money">Контейнер ресурсов · 15 CR и 1 зелье</button><button id="cacheRelics">ОТКРЫТЬ ОТСЕК РЕЛИКВИЙ →</button>`);$('#cacheRelics').onclick=()=>relicChoices(o);$('#weapon').onclick=()=>{player.atk+=3;player.weapon='Импульсный клинок MK II';doneEvent(o,'Оружие улучшено.')};$('#armor').onclick=()=>{player.armor+=2;player.suit='Композитная броня';doneEvent(o,'Броня усилена.')};$('#module').onclick=()=>{player.max+=15;player.hp=Math.min(player.max,player.hp+25);player.module='Модуль жизни';doneEvent(o,'Модуль установлен.')};$('#money').onclick=()=>{player.coins+=15;player.potions++;doneEvent(o,'+15 CR и зелье.')}}else if(o.type==='trap'){panel(`<span class="eyebrow">ОХРАННАЯ СИСТЕМА</span><h2>Лазерная ловушка.</h2><p class="muted">Можно отключить питание за 5 CR или пройти через разряд. Разряд отнимет 15 HP и может убить.</p><div class="row"><button id="disarm" ${player.coins<5?'disabled':''}>ОТКЛЮЧИТЬ · 5 CR</button><button id="risk" class="danger">ПРОЙТИ · −15 HP</button><button id="back">УЙТИ</button></div>`);$('#disarm').onclick=()=>{player.coins-=5;doneEvent(o,'Ловушка обезврежена. +8 CR');player.coins+=8;save()};$('#risk').onclick=()=>{player.hp=Math.max(0,player.hp-15);doneEvent(o,'Разряд получен. +8 CR');player.coins+=8;if(player.hp<=0)finish(false);else save()};$('#back').onclick=()=>{overlay.innerHTML='';resumeRoute(o)}}else if(['merchant','medic','drone','terminal'].includes(o.type)){extraEvent(o)}else{const questions=[['Какой алгоритм учитывает стоимость пути и эвристику?',['DFS','A*','BFS'],1,'A* использует f(n) = g(n) + h(n): пройденную стоимость и оценку остатка.'],['Для чего нужен Alpha-Beta?',['Для генерации случайных чисел','Для обучения нейросети','Для отсечения ветвей Minimax'],2,'Alpha-Beta сохраняет результат Minimax, пропуская ветви, которые не изменят решение.'],['Из чего состоит CSP?',['Переменные, домены, ограничения','Только случайные координаты','Здоровье, урон, броня'],0,'Решатель назначает переменным значения из доменов, соблюдая ограничения.']];const q=questions[Math.abs([...seed].reduce((s,c)=>s+c.charCodeAt(0),0))%3];panel(`<span class="eyebrow">АРХИВ / ПРОВЕРКА ДОСТУПА</span><h2>${q[0]}</h2><p class="muted">Верный ответ: 12 CR и восстановление 15 HP. Ошибка: без награды.</p>${q[1].map((t,i)=>`<button class="choice" data-answer="${i}">${i+1}. ${t}</button>`).join('')}`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.answer===q[2];if(ok){player.coins+=12;player.hp=Math.min(player.max,player.hp+15)}panel(`<span class="eyebrow">${ok?'ДОСТУП ОТКРЫТ':'ПРОВЕРКА ЗАВЕРШЕНА'}</span><h2>${ok?'Ответ верный.':'Архив объясняет.'}</h2><p>${q[3]}</p><button class="primary" id="done">ПРОДОЛЖИТЬ</button>`);$('#done').onclick=()=>doneEvent(o,ok?'+12 CR · +15 HP':'Знание получено.')} )}}
function extraEvent(o){const next=Object.keys(RELICS).find(k=>!player.passives?.[k]);const choices=o.type==='merchant'?[['buyPotion','Два зелья · 8 CR',8,()=>{player.potions+=2;return '+2 зелья'}],['buyRelic',next?'Реликвия «'+RELICS[next].name+'» · 12 CR':'Усиление клинка +3 · 12 CR',12,()=>{if(next){player.passives??={};player.passives[next]=true}else player.atk+=3;return 'Покупка получена'}]]:o.type==='medic'?[['medHeal','Восстановить 35 HP · 8 CR',8,()=>{player.hp=Math.min(player.max,player.hp+35);return 'Медстанция: +35 HP'}],['medSalvage','Забрать аптечку · +1 зелье',0,()=>{player.potions++;return '+1 зелье'}]]:o.type==='drone'?[['droneRepair','Восстановить дрона · 6 CR · '+(player.passives?.shield?'броня +1':'Аварийный щит'),6,()=>{player.passives??={};if(player.passives.shield)player.armor++;else player.passives.shield=true;return 'Дрон прикрывает вас'}],['droneSalvage','Разобрать дрона · +10 CR',0,()=>{player.coins+=10;return '+10 CR'}]]:[['terminalClear','Отключить опасные покрытия в радиусе 4 клеток · 5 CR',5,()=>{let count=0;for(let i=0;i<map.cells.length;i++)if(map.cells[i]>1&&Math.abs(i%map.n-o.id%map.n)+Math.abs(Math.floor(i/map.n)-Math.floor(o.id/map.n))<=4){map.cells[i]=1;count++}return 'Безопасных клеток: '+count}],['terminalData','Продать данные · +8 CR',0,()=>{player.coins+=8;return '+8 CR'}]];panel('<span class="eyebrow">КОНТАКТ / РЕШЕНИЕ</span><h2>'+objectName(o)+'</h2><p class="muted">Один выбор на забег. Награда или улучшение — решите, что сейчас полезнее.</p>'+choices.map(([id,text,cost])=>'<button class="choice" id="'+id+'" '+(player.coins<cost?'disabled':'')+'>'+text+'</button>').join('')+'<button id="eventLeave">ПРОЙТИ МИМО</button>');for(const[id,text,cost,apply]of choices)$('#'+id).onclick=()=>{if(player.coins<cost)return;player.coins-=cost;doneEvent(o,apply())};$('#eventLeave').onclick=()=>doneEvent(o,'Контакт завершён')}
function doneEvent(o,msg){currentEvent=null;o.done=true;events++;overlay.innerHTML='';const resumed=resumeRoute(o);toast(msg+(resumed?' · маршрут продолжается':''));save();beep(750)}
function finish(win){cancelRoute();mode='end';$('#combat').hidden=true;$('#drawer').hidden=true;localStorage.removeItem('neonSave');panel(`<span class="eyebrow">${runStats.devUsed?'DEV / ТЕСТОВЫЙ ЗАБЕГ · ':''}${win?'ПРОТОКОЛ ЗАВЕРШЁН':'СИГНАЛ ПОТЕРЯН'}</span><h1>${win?'ВЫХОД<br><em>ОТКРЫТ.</em>':'ЕЩЁ ОДИН<br><em>ШАНС.</em>'}</h1><p class="muted">${win?'Хранитель отключён. Комплекс больше не управляет твоим маршрутом.':'Комплекс оказался сильнее. Другой путь и правильная подготовка могут изменить исход.'}</p><div class="cards"><div class="card"><strong>${kills}</strong>побед</div><div class="card"><strong>${events}/3</strong>события</div><div class="card"><strong>${Math.floor(elapsed/60)}:${String(Math.floor(elapsed%60)).padStart(2,'0')}</strong>время</div></div><p class="muted">Исследовано: ${Math.round(explored.filter((v,i)=>v&&map.cells[i]).length/map.cells.filter(Boolean).length*100)}% · Истощение: ${(runStats.exhaustion||0).toFixed(1)} HP<br>Маршруты: ${Object.entries(runStats.launches||{}).map(([k,v])=>k.toUpperCase()+': '+v).join(' · ')||'нет'}<br>Реликвии: ${Object.keys(player.passives||{}).filter(k=>player.passives[k]&&RELICS[k]).map(k=>RELICS[k].name).join(', ')||'нет'}</p><p class="muted">Seed: ${seed.replace(/[<>&"']/g,'')} · Остаток: ${player.coins} CR · ${Math.ceil(player.hp)} HP</p><button class="primary" id="again">НОВЫЙ ЗАБЕГ →</button>`);$('#again').onclick=menu;beep(win?1000:90,.5)}
addEventListener('keydown',e=>{if(e.code==='F2'||e.key==='F2'){e.preventDefault();if(!e.repeat)toggleDev();return}if(devOpen){if(e.key==='Escape'){e.preventDefault();closeDev()}return}if(['INPUT','SELECT'].includes(e.target.tagName))return;const k=({KeyE:'e',KeyQ:'q',KeyM:'m',KeyW:'w',KeyA:'a',KeyS:'s',KeyD:'d'})[e.code]||e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){if(mode==='explore'&&!paused&&!overlay.innerHTML){if(!firstStepDone){if(!e.repeat)toast('Первый шаг — через навигатор. M → цель → DFS (бесплатно).');return}keys[k]=true;cancelRoute();if(!e.repeat)manualMove(.04);}return}if(e.repeat)return;if(k===' '){cancelRoute();toast('Движение остановлено.');}if(k==='q'&&mode==='explore'&&!overlay.innerHTML&&!paused){if(player.potions&&player.hp<player.max){player.potions--;const amt=Math.min(25,player.max-player.hp);player.hp+=amt;fx.push({x:player.x,y:player.y,action:'heal',amount:amt,age:0,life:1.25});toast('Зелье: +'+amt+' HP');save();beep(700)}else toast(player.potions?'Здоровье полное.':'Зелья закончились.')}if(k==='escape')pause();if(k==='m')openMap();if(k==='e'&&near&&mode==='explore'&&!overlay.innerHTML)encounter(near)});addEventListener('keyup',e=>{const k=({KeyW:'w',KeyA:'a',KeyS:'s',KeyD:'d'})[e.code]||e.key.toLowerCase();delete keys[k]});addEventListener('blur',()=>{keys={};if(started&&!devOpen&&mode!=='menu'&&mode!=='end'&&!overlay.innerHTML)pause()});
canvas.addEventListener('click',e=>{if(mode!=='explore'||paused||overlay.innerHTML)return;const x=Math.floor((e.clientX-W/2+cam.x)/TILE),y=Math.floor((e.clientY-H*.46+cam.y)/TILE),id=y*map.n+x;if(x<0||y<0||x>=map.n||y>=map.n||!selectable(id))return;openMap();target=id;$('#targetText').textContent='Цель: ['+x+', '+y+']';showRouteOptions(id);drawMini()});
function pass(x,y){for(const[dx,dy]of[[-.19,-.19],[.19,-.19],[-.19,.19],[.19,.19]]){const a=Math.floor(x+dx),b=Math.floor(y+dy);if(a<0||b<0||a>=map.n||b>=map.n||!map.cells[b*map.n+a])return false}return true}
function manualPass(x,y){if(!pass(x,y))return false;return [[-.19,-.19],[.19,-.19],[-.19,.19],[.19,.19]].every(([a,b])=>explored[Math.floor(y+b)*map.n+Math.floor(x+a)])}
function movementCost(distance,algorithm=false){walk+=distance;anim+=distance*8;runStats[algorithm?'algorithm':'manual']=(runStats[algorithm?'algorithm':'manual']||0)+distance;if(visited.length!==map.cells.length){visited=Array(map.cells.length).fill(false);visited[cell()]=true}const id=cell();if(distance>0&&!visited[id]){const cost=algorithm?firstVisitCost(map,id,visited,player.passives):0,loss=Math.min(Math.max(0,player.hp-10),cost);visited[id]=true;player.hp-=loss;if(loss){runStats.exhaustion=(runStats.exhaustion||0)+loss;lastLoss={text:'Первый проход · '+(map.cells[id]===5?'опасная зона':map.cells[id]===3?'завал':'разведка')+' −'+loss.toFixed(1)+' HP',until:elapsed+3}}save()}if(algorithm&&!firstStepDone){firstStepDistance+=distance;if(firstStepDistance>=.5){firstStepDone=true;toast('Навигатор откалиброван! WASD / стрелки — по открытым клеткам. M — новый маршрут.');save()}}if(lastReveal!==cell()){reveal(algorithm);save()}}
function manualMove(dt){if(!firstStepDone)return;let dx=+(!!(keys.d||keys.arrowright))-+(!!(keys.a||keys.arrowleft)),dy=+(!!(keys.s||keys.arrowdown))-+(!!(keys.w||keys.arrowup));const len=Math.hypot(dx,dy);if(!len)return;cancelRoute();dx/=len;dy/=len;let distance=0;const steps=Math.max(1,Math.ceil(dt*3.1/.12)),amount=dt*3.1/steps;for(let i=0;i<steps;i++){const x=player.x,y=player.y;if(manualPass(x+dx*amount,y))player.x+=dx*amount;if(manualPass(player.x,y+dy*amount))player.y+=dy*amount;distance+=Math.hypot(player.x-x,player.y-y);if(lastReveal!==cell())reveal(false);if(visited.length===map.cells.length)visited[cell()]=true}if(!distance&&elapsed-blockedHintAt>2){blockedHintAt=elapsed;toast('Стена или неизвестная территория. Для разведки: M → цель → алгоритм.')}movementCost(distance);if(distance)save()}
function update(dt){if(!map||mode==='menu')return;for(const f of fx)if(!paused)f.age+=dt;fx=fx.filter(f=>f.age<f.life);for(const d of deaths)if(!paused)d.age+=dt;deaths=deaths.filter(d=>d.age<1);if(mode==='combat'&&!paused&&!overlay.innerHTML)elapsed+=dt;if(mode==='explore'&&!paused&&!overlay.innerHTML){elapsed+=dt;if(lastReveal!==cell())reveal(false);if(!autoWalk)manualMove(dt);if(autoWalk){while(autoIndex<route.length&&Math.hypot(route[autoIndex]%map.n+.5-player.x,Math.floor(route[autoIndex]/map.n)+.5-player.y)<.015)autoIndex++;if(autoIndex>=route.length){cancelRoute();save();toast('Цель достигнута.')}else{const dx=route[autoIndex]%map.n+.5-player.x,dy=Math.floor(route[autoIndex]/map.n)+.5-player.y,len=Math.hypot(dx,dy),dist=Math.min(len,dt*3.1*speed);let moved=0;const ax=dx/len*dist,ay=dy/len*dist;if(pass(player.x+ax,player.y)){player.x+=ax;moved+=ax*ax}if(pass(player.x,player.y+ay)){player.y+=ay;moved+=ay*ay}const distance=Math.sqrt(moved);movementCost(distance,true)}}near=null;let best=1.3;for(const o of map.objects)if(activeObject(o)&&visible.has(o.id)){const d=Math.hypot(o.id%map.n+.5-player.x,Math.floor(o.id/map.n)+.5-player.y);if(d<best){best=d;near=o}}if(autoWalk&&firstStepDone&&near&&near.id!==autoIgnore){suspendRoute(near);save();toast('Маршрут приостановлен: '+objectName(near)+'. E — взаимодействовать.');}$('#interact').style.display=near?'block':'none';if(near)$('#interact').textContent='E · '+(near.type==='enemy'?'СРАЗИТЬСЯ: '+names[near.kind]:near.type==='boss'?'БОЙ С ХРАНИТЕЛЕМ':near.type==='cache'?'ОТКРЫТЬ ТАЙНИК':objectName(near).toUpperCase())}else $('#interact').style.display='none';const cx=player.x*TILE,cy=player.y*TILE;cam.x+=(cx-cam.x)*Math.min(1,dt*7);cam.y+=(cy-cam.y)*Math.min(1,dt*7);flash=Math.max(0,flash-dt);$('#loss').textContent=lastLoss&&elapsed<lastLoss.until?lastLoss.text:'Возврат по пройденным клеткам: 0 HP';$('#coords').textContent='X '+player.x.toFixed(1)+' · Y '+player.y.toFixed(1)+' · СИГНАЛ СТАБИЛЕН ●';$('#hud').innerHTML=`<div><span class="label">ЖИЗНЬ</span> ${Math.ceil(player.hp)} / ${player.max}<div class="hp"><b style="width:${player.hp/player.max*100}%"></b></div></div><div><span class="label">ЭНЕРГИЯ</span><br><span style="color:var(--cyan)">${'◆'.repeat(player.energy)}${'◇'.repeat(3-player.energy)}</span></div><div class="gold">${player.coins} CR<br><small>${player.potions} зелий</small></div>`;$('#mission').innerHTML=`${runStats.devUsed?'<span class="dev-badge">DEV · ТЕСТОВЫЙ ЗАБЕГ</span><br>':''}<span class="label" style="color:var(--pink)">${bossAwake?'ФИНАЛЬНЫЙ ПРОТОКОЛ':'СНЯТЬ ПЯТЬ ПЕЧАТЕЙ'}</span><br>${bossAwake?'Найти и победить Хранителя':'Победить всех противников'}<br><span class="muted">Противники ${kills}/5 · Открыто ${Math.round(explored.filter((v,i)=>v&&map.cells[i]).length/map.cells.filter(Boolean).length*100)}%<br>${pendingRoute!==null?'Маршрут приостановлен · E — завершить встречу':autoWalk?'Маршрут: '+routeInfo.alg.toUpperCase()+' · ×'+speed:(firstStepDone?'WASD / стрелки — ходить · M — маршрут':'Первый шаг: M → цель → алгоритм')}</span>`}

function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function sprite(x,y,type,t=0,scale=1,variant=0){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(scale,scale);const reaction=fx.find(f=>Math.abs(f.x*TILE-x)<4&&Math.abs(f.y*TILE-y)<4&&f.age<.3);if(reaction)ctx.translate(Math.sin(reaction.age/.3*Math.PI)*(reaction.action==='guard'?2:7),0);const moving=type==='hero'?Math.sin(anim)*2:Math.sin(t*2)*1;ctx.fillStyle='#0008';ctx.beginPath();ctx.ellipse(0,16,13,5,0,0,7);ctx.fill();ctx.translate(0,moving);if(type==='hero'){ctx.shadowColor='#55efdb';ctx.shadowBlur=12;rect(-6,-19,12,11,'#e1e9f3');ctx.shadowBlur=0;rect(-8,-16,4,8,'#8c9eb9');rect(-5,-11,10,4,'#55efdb');rect(-7,-6,14,14,'#4a526e');rect(-11,-4,4,11,'#8998b0');rect(8,-4,4,10,'#8998b0');rect(-6,8,5,10+(Math.sin(anim)*2),'#263b54');rect(2,8,5,10-(Math.sin(anim)*2),'#263b54');rect(12,-1,3,22,'#55efdb');rect(-2,-5,4,10,'#7a81a4')}else if(type==='boss'){ctx.shadowColor='#f559a7';ctx.shadowBlur=20;rect(-19,-22,38,35,'#37273f');rect(-12,-30,24,13,'#9b526f');rect(-8,-24,16,4,'#ff679f');rect(-27,-14,10,27,'#6e3c5a');rect(17,-14,10,27,'#6e3c5a');rect(-14,13,9,14,'#44415c');rect(5,13,9,14,'#44415c');rect(-5,-10,10,10,'#ff679f');ctx.shadowBlur=0}else if(type==='enemy'){rect(-9,-16,18,12,variant===0?'#9099ac':variant===1?'#b5687a':'#8799b7');rect(-7,-12,14,3,'#ff5b9f');rect(-11,-3,22,17,'#423750');rect(-15,-1,5,14,'#76627d');rect(10,-1,5,14,'#76627d');rect(-8,14,6,8,'#352b46');rect(3,14,6,8,'#352b46');rect(-4,1,8,4,variant===2?'#b39cff':'#f559a7');if(variant===0){rect(-19,-2,8,23,'#697991');rect(-17,1,4,16,'#ec71b1')}if(variant===2){rect(11,0,6,13,'#947cc9');rect(12,2,4,6,'#b7a0ff')}}else if(type==='cache'){rect(-16,-10,32,24,'#66553b');rect(-16,-10,32,7,'#a08850');rect(-17,-3,34,3,'#c7a55e');ctx.shadowColor='#eac47b';ctx.shadowBlur=14;rect(-3,-2,6,9,'#ffe1a1');ctx.shadowBlur=0;rect(-14,12,28,3,'#2b2c38')}else{ctx.strokeStyle='#9780d4';ctx.lineWidth=2;ctx.strokeRect(-15,-15,30,30);rect(-12,-12,24,24,'#292a4d');ctx.fillStyle='#b2a1f6';ctx.font='bold 21px monospace';ctx.textAlign='center';ctx.fillText('?',0,8)}ctx.restore()}
function draw(t){ctx.fillStyle='#060913';ctx.fillRect(0,0,W,H);if(!map){for(let y=0;y<H;y+=55)for(let x=0;x<W;x+=55){rect(x+1,y+1,53,53,'#0c1120');if((x/55+y/55)%7===0){ctx.strokeStyle='#1a3f48';ctx.strokeRect(x+6,y+6,43,43)}}const a=ctx.createRadialGradient(W*.3,H*.45,10,W*.3,H*.45,H*.7);a.addColorStop(0,'#26395470');a.addColorStop(1,'#05091600');ctx.fillStyle=a;ctx.fillRect(0,0,W,H);return}let zoom=mode==='combat'?1.3:1,ox=W/2-cam.x*zoom,oy=H*.46-cam.y*zoom;if(mode==='combat'&&battle){const bx=battle.object.id%map.n+.5,by=Math.floor(battle.object.id/map.n)+.5;ox=W/2-(player.x+bx)/2*TILE*zoom;oy=H*.29-(player.y+by)/2*TILE*zoom;}ctx.save();ctx.translate(ox,oy);ctx.scale(zoom,zoom);const minX=Math.max(0,Math.floor((-ox/zoom)/TILE)-1),maxX=Math.min(map.n,Math.ceil((W-ox)/zoom/TILE)+1),minY=Math.max(0,Math.floor(-oy/zoom/TILE)-1),maxY=Math.min(map.n,Math.ceil((H-oy)/zoom/TILE)+1);for(let y=minY;y<maxY;y++)for(let x=minX;x<maxX;x++){const id=y*map.n+x,px=x*TILE,py=y*TILE,c=map.cells[id];if(!explored[id])continue;if(c){rect(px,py,TILE,TILE,bossAwake?((x+y)%2?'#271a30':'#20172b'):((Math.floor(x/6)+Math.floor(y/6))%3===0?'#17252c':(Math.floor(x/6)+Math.floor(y/6))%3===1?'#1b2133':'#231f30'));rect(px+2,py+2,TILE-4,1,'#202b3c');rect(px+2,py+TILE-2,TILE-4,1,'#090f1a');if((x*7+y*11)%13===0){rect(px+8,py+12,15,2,'#253145');rect(px+32,py+40,9,2,'#202e43')}if(c===3){rect(px+12,py+19,13,12,'#675944');rect(px+29,py+29,15,10,'#514c40');rect(px+23,py+11,9,8,'#7b6b50')}if(c===5){rect(px+7,py+10,42,34,'#342138');for(let a=0;a<4;a++)rect(px+10+a*10,py+13,4,28,'#793b61');rect(px+8,py+44,40,2,'#eb57949c')}}else{rect(px,py,TILE,TILE,'#090e19');if(y+1<map.n&&map.cells[id+map.n]){rect(px,py+TILE-16,TILE,16,'#27344b');rect(px+2,py+TILE-16,TILE-4,3,'#426079');rect(px+4,py+TILE-4,TILE-8,2,'#55efdb65')}if(x+1<map.n&&map.cells[id+1])rect(px+TILE-3,py,2,TILE,'#2a5661');if(x>0&&map.cells[id-1])rect(px+1,py,2,TILE,'#263f52');if((x+y*3)%9===0){rect(px+8,py+12,38,28,'#111a2b');rect(px+12,py+17,18,2,'#2c5c69');rect(px+12,py+23,27,2,'#233b56')}}}if(route.length){ctx.strokeStyle='#55efdb99';ctx.lineWidth=3;ctx.setLineDash([5,8]);ctx.lineDashOffset=-t*12;ctx.beginPath();route.forEach((i,k)=>{if(!explored[i])return;const x=(i%map.n+.5)*TILE,y=(Math.floor(i/map.n)+.5)*TILE;k&&explored[route[k-1]]?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.setLineDash([])}for(const o of map.objects){if(!visible.has(o.id)||(o.type==='boss'&&!bossAwake))continue;const x=(o.id%map.n+.5)*TILE,y=(Math.floor(o.id/map.n)+.5)*TILE;if(o.done){rect(x-8,y-2,16,4,'#334452');continue}const col=o.type==='enemy'||o.type==='boss'?'#f559a7':o.type==='cache'?'#eac47b':'#aa8de3';const glow=ctx.createRadialGradient(x,y,2,x,y,65);glow.addColorStop(0,col+'25');glow.addColorStop(1,col+'00');ctx.fillStyle=glow;ctx.fillRect(x-65,y-65,130,130);sprite(x,y,o.type,t,1,o.kind);if(o===near){ctx.strokeStyle=col;ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(x,y+15,23,11,0,0,7);ctx.stroke()}}drawFog(t);drawBeacons(t);if(route.length){const goal=route.at(-1),gx=(goal%map.n+.5)*TILE,gy=(Math.floor(goal/map.n)+.5)*TILE;ctx.strokeStyle='#fff5bc';ctx.lineWidth=2;ctx.beginPath();ctx.arc(gx,gy,25+Math.sin(t*3)*3,0,7);ctx.stroke();ctx.fillStyle='#fff5bc';ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText('ЦЕЛЬ',gx,gy-33)}for(const d of deaths){ctx.save();ctx.globalAlpha=1-d.age;ctx.translate(0,d.age*14);sprite(d.x*TILE,d.y*TILE,d.type,t,1,d.kind);ctx.restore()}const px=player.x*TILE,py=player.y*TILE;let g=ctx.createRadialGradient(px,py,0,px,py,110);g.addColorStop(0,'#55efdb18');g.addColorStop(1,'#55efdb00');ctx.fillStyle=g;ctx.fillRect(px-110,py-110,220,220);sprite(px,py,'hero',t);if(flash>0){ctx.fillStyle='#f559a7'+Math.floor(flash*150).toString(16).padStart(2,'0');ctx.fillRect(px-20,py-25,40,50)}if(mode==='combat'&&battle){const o=battle.object,x=(o.id%map.n+.5)*TILE,y=(Math.floor(o.id/map.n)+.5)*TILE;rect(x-24,y-43,48,4,'#382b40');rect(x-24,y-43,48*battle.s[1].hp/battle.s[1].max,4,'#f559a7');if(battle.charge){ctx.fillStyle='#ffcc8b';ctx.font='bold 18px monospace';ctx.textAlign='center';ctx.fillText('!',x,y-52)}}drawEffects();ctx.restore();ctx.fillStyle='#6acabc20';for(let i=0;i<22;i++){const x=(i*173.3+t*(i%3+1)*5)%W,y=(i*91.7+t*8)%H;ctx.fillRect(x,y,1.5,1.5)}}
function frame(ts){let dt=Math.min(.035,(ts-lastTime)/1000||.016);lastTime=ts;update(dt);draw(ts/1000);requestAnimationFrame(frame)}menu();requestAnimationFrame(frame);

function drawEffects(){for(const f of fx){const a=f.age/f.life,x=f.x*TILE,y=f.y*TILE-40-a*38;ctx.save();ctx.translate(x,y);ctx.globalAlpha=1-Math.pow(a,2);const scale=1+Math.sin(Math.min(1,a*4)*Math.PI)*.3;ctx.scale(scale,scale);const shield=f.action==='guard'||f.action==='pierce',heal=f.action==='heal';ctx.strokeStyle=shield?'#78c9ff':heal?'#92ffb2':'#ff769c';ctx.fillStyle=shield?'#234a70':heal?'#3fbe7a':'#d84e80';ctx.lineWidth=2;if(shield){ctx.beginPath();ctx.moveTo(-12,-12);ctx.lineTo(12,-12);ctx.lineTo(10,4);ctx.lineTo(0,14);ctx.lineTo(-10,4);ctx.closePath();ctx.fill();ctx.stroke();if(f.action==='pierce'){ctx.beginPath();ctx.moveTo(4,-10);ctx.lineTo(-4,0);ctx.lineTo(4,3);ctx.lineTo(-3,12);ctx.stroke()}}else{ctx.beginPath();ctx.moveTo(0,12);ctx.bezierCurveTo(-28,-5,-12,-24,0,-10);ctx.bezierCurveTo(12,-24,28,-5,0,12);ctx.fill();ctx.stroke()}ctx.fillStyle='#f4faff';ctx.font='bold 17px monospace';ctx.textAlign='center';ctx.fillText(f.amount?(heal?'+':'−')+f.amount:shield?'ЩИТ':'',0,-23);ctx.restore()}}

function drawBeacons(t){for(const o of map.objects){if(!activeObject(o)||visible.has(o.id))continue;const x=(o.id%map.n+.5)*TILE,y=(Math.floor(o.id/map.n)+.5)*TILE,col=o.type==='enemy'?'#f559a7':o.type==='boss'?'#ff666f':o.type==='cache'?'#eac47b':o.type==='trap'?'#ff9f78':'#b9a1ff';ctx.save();ctx.translate(x,y);ctx.shadowColor=col;ctx.shadowBlur=13;ctx.fillStyle='#0c1428';ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,17+Math.sin(t*2)*1.5,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle=col;ctx.font='bold 21px monospace';ctx.textAlign='center';ctx.fillText(o.type==='enemy'?'⚔':o.type==='cache'?'◆':o.type==='trap'?'!':o.type==='boss'?'✦':'?',0,7);ctx.font='10px monospace';ctx.fillText(o.type==='enemy'?'ПРОТИВНИК':o.type==='cache'?'ПОДАРОК':o.type==='trap'?'ЛОВУШКА':o.type==='boss'?'ХРАНИТЕЛЬ':'СОБЫТИЕ',0,35);ctx.restore()}}

function fogOpacity(id){if(!explored[id])return 1;const distance=Math.hypot(id%map.n+.5-player.x,Math.floor(id/map.n)+.5-player.y),u=Math.min(1,distance/4.5),smooth=u*u*(3-2*u);return visible.has(id)? .04+.68*smooth:.76}
function drawFog(t){if(!fogCanvas)fogCanvas=document.createElement('canvas');if(fogCanvas.width!==map.n){fogCanvas.width=map.n;fogCanvas.height=map.n}const g=fogCanvas.getContext('2d'),image=g.createImageData(map.n,map.n);for(let id=0;id<map.cells.length;id++){const goal=fogOpacity(id);fogLevels[id]=fogLevels[id]===undefined?goal:fogLevels[id]+(goal-fogLevels[id])*.09;image.data[id*4]=2;image.data[id*4+1]=5;image.data[id*4+2]=11;image.data[id*4+3]=Math.round(fogLevels[id]*255)}g.putImageData(image,0,0);ctx.save();ctx.imageSmoothingEnabled=true;ctx.filter='blur(15px)';ctx.drawImage(fogCanvas,0,0,map.n*TILE,map.n*TILE);ctx.restore()}

// Developer controls use the same encounter/reward transitions as normal play.
function devCurrent(){return battle?.object||(currentEvent&&overlay.innerHTML&&activeObject(currentEvent)?currentEvent:null)||(near&&activeObject(near)?near:null)}
function toggleDev(){if(devOpen){closeDev();return}devWasPaused=paused;devOpen=true;paused=true;keys={};renderDev()}
function closeDev(){devOpen=false;$('#devPanel').hidden=true;paused=devWasPaused;keys={}}
function devTouch(){if(!runStats.devUsed){save();const raw=localStorage.getItem('neonSave');if(raw)localStorage.setItem('neonSaveBeforeDev',raw)}runStats.devUsed=true;try{const s=JSON.parse(localStorage.getItem('neonSave'));if(s){s.runStats??={};s.runStats.devUsed=true;localStorage.setItem('neonSave',JSON.stringify(s))}}catch{}$('#devBtn').textContent='DEV* · F2'}
function devResetScene(){cancelRoute();battle=null;battleStats=null;enemyTurn=false;currentEvent=null;near=null;keys={};$('#combat').hidden=true;$('#drawer').hidden=true;overlay.innerHTML='';overlay.dataset.kind='';mode='explore';paused=false;devWasPaused=false}
function devWarp(id,boss=false){if(!started||mode==='menu'||mode==='end')return false;const o=map.objects.find(o=>o.id===id&&!o.done);if(!o||o.type==='boss'&&!boss&&!bossAwake)return false;devTouch();devResetScene();if(boss){for(const enemy of map.objects.filter(o=>o.type==='enemy'))enemy.done=true;kills=5;bossAwake=true;prepared=true;player.hp=player.max;player.energy=3}player.x=id%map.n+.5;player.y=Math.floor(id/map.n)+.5;firstStepDone=true;firstStepDistance=1;visited[id]=true;reveal();cam={x:player.x*TILE,y:player.y*TILE};closeDev();save();encounter(o);toast('DEV: переход к '+objectName(o));return true}
function devRefreshEvent(){if(mode==='explore'&&overlay.innerHTML&&currentEvent&&activeObject(currentEvent)&&['merchant','medic','drone','terminal','trap'].includes(currentEvent.type))event(currentEvent)}
function devAction(action){if(action==='restore'){const raw=localStorage.getItem('neonSaveBeforeDev');try{if(!validSave(JSON.parse(raw)))throw 0}catch{toast('Нет сохранения до использования DEV.');return false}devResetScene();closeDev();localStorage.setItem('neonSave',raw);load();$('#devBtn').textContent=runStats.devUsed?'DEV* · F2':'DEV · F2';toast('Прогресс до DEV восстановлен.');return true}
if(action==='demo'){if(mode!=='menu')return false;closeDev();start();overlay.innerHTML='';devTouch();firstStepDone=true;firstStepDistance=1;save();toast('DEV: демозабег готов. F2 — переходы и пропуск.');return true}
if(!started||['menu','end'].includes(mode))return false;
const current=devCurrent();if(action==='skip'&&!current)return false;devTouch();
if(action==='heal'){player.hp=player.max;player.energy=3;player.potions=Math.max(player.potions,5);if(battle){Object.assign(battle.s[0],{hp:player.hp,energy:3,potions:player.potions});planIntent();renderBattle()}devRefreshEvent();save();toast('DEV: здоровье и энергия восстановлены.');renderDev();return true}
if(action==='resources'){player.coins+=100;player.potions+=5;if(battle)battle.s[0].potions=player.potions;devRefreshEvent();save();toast('DEV: +100 CR и +5 зелий.');renderDev();return true}
if(action==='reveal'){explored.fill(true);visited.fill(true);firstStepDone=true;firstStepDistance=1;reveal(false);fogLevels=[];save();toast('DEV: карта открыта, свободное движение доступно.');renderDev();return true}
if(action==='skip'){closeDev();paused=false;devWasPaused=false;if(battle){enemyTurn=false;battle.s[1].hp=0;winBattle()}else{overlay.innerHTML='';paused=false;doneEvent(current,'DEV: событие пропущено без награды')}return true}
if(action==='final'){devResetScene();for(const o of map.objects)if(o.type==='enemy'||o.type==='boss')o.done=true;kills=5;bossAwake=true;prepared=true;closeDev();finish(true);return true}return false}
function renderDev(){const playing=started&&!['menu','end'].includes(mode),current=playing?devCurrent():null,boss=playing?map.objects.find(o=>o.type==='boss'&&!o.done):null;const box=$('#devPanel');box.hidden=false;box.innerHTML='<div class="dev-head"><span class="eyebrow">DEV / ПРОВЕРКА И ДЕМОНСТРАЦИЯ</span><button id="devClose" aria-label="Закрыть режим разработчика">×</button></div><h2>Пропустить до нужного момента</h2><p class="muted">Игра приостановлена. Действия помечают забег как тестовый. Сохраняется точка возврата до первого изменения DEV.</p>'+(playing?'<div class="dev-status">'+Math.ceil(player.hp)+' / '+player.max+' HP · '+player.coins+' CR · '+kills+'/5 врагов</div><div class="dev-grid"><button id="devHeal">Восстановить HP и энергию</button><button id="devResources">+100 CR и +5 зелий</button><button id="devReveal">Открыть всю карту</button><button id="devSkip" '+(!current?'disabled':'')+'>Пропустить встречу'+(current?': '+objectName(current):'')+'</button><button id="devBoss" '+(!boss?'disabled':'')+'>Сразу к боссу · пропустить 5 боёв</button><button id="devFinal">Показать финал победы</button></div><h3>ПЕРЕЙТИ К ОБЪЕКТУ</h3><div class="dev-targets">'+map.objects.filter(o=>activeObject(o)&&o.type!=='boss').map(o=>'<button data-dev-target="'+o.id+'">'+objectName(o)+' ['+o.id%map.n+', '+Math.floor(o.id/map.n)+']</button>').join('')+'</div>':mode==='menu'?'<button id="devDemo" class="primary">НАЧАТЬ ДЕМОЗАБЕГ</button>':'<p>Забег завершён. Можно восстановить прогресс до DEV или начать новый забег в меню.</p>')+'<div class="divider"></div><button id="devRestore" '+(!localStorage.getItem('neonSaveBeforeDev')?'disabled':'')+'>Вернуться к сохранению до DEV</button><p class="muted">F2 — открыть / закрыть. Пропуск боя даёт обычную победу с выбором трофея; пропуск события не выдаёт награду.</p>';$('#devClose').onclick=closeDev;$('#devRestore').onclick=()=>devAction('restore');if(playing){$('#devHeal').onclick=()=>devAction('heal');$('#devResources').onclick=()=>devAction('resources');$('#devReveal').onclick=()=>devAction('reveal');$('#devSkip').onclick=()=>devAction('skip');$('#devBoss').onclick=()=>boss&&devWarp(boss.id,true);$('#devFinal').onclick=()=>devAction('final');document.querySelectorAll('[data-dev-target]').forEach(b=>b.onclick=()=>devWarp(+b.dataset.devTarget))}else if(mode==='menu')$('#devDemo').onclick=()=>devAction('demo')}
$('#devBtn').onclick=toggleDev;
